const supportItems = $items('Read Support Log (All)').map(i => i.json || {});
const pendingItems = $items('Read Pending Actions Queue').map(i => i.json || {});

function safe(v, d = '') {
  if (v === undefined || v === null) return d;
  return String(v);
}

function parseDateOnly(ts) {
  if (!ts) return null;
  const s = String(ts);
  if (s.includes('T')) return s.split('T')[0];
  // If already just a date like 2025-11-06
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  return null;
}

function htmlEscape(str) {
  return safe(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const todayIso = new Date().toISOString().slice(0, 10);

// Filter today's support activity (by timestamp date part)
const todaysSupport = supportItems.filter(r => parseDateOnly(r.timestamp) === todayIso);

let totalMessages = todaysSupport.length;
let byCategory = {};
let byDraftStatus = {};
let needsAdminCount = 0;
let createTaskCount = 0;
let autoSendCount = 0;
let processedCount = 0;

for (const r of todaysSupport) {
  const cat = (safe(r.category) || 'uncategorised').toLowerCase() || 'uncategorised';
  byCategory[cat] = (byCategory[cat] || 0) + 1;

  const st = safe(r.draft_status) || 'unknown';
  byDraftStatus[st] = (byDraftStatus[st] || 0) + 1;

  const needsAdmin = String(r.needs_admin).toUpperCase() === 'TRUE' || r.needs_admin === true;
  const createTask = String(r.create_task).toUpperCase() === 'TRUE' || r.create_task === true;
  const autoSend = String(r.auto_send_eligible).toUpperCase() === 'TRUE' || r.auto_send_eligible === true;
  const processed = String(r.processed).toUpperCase() === 'TRUE' || r.processed === true;

  if (needsAdmin) needsAdminCount++;
  if (createTask) createTaskCount++;
  if (autoSend) autoSendCount++;
  if (processed) processedCount++;
}

// Pending actions: open / pending & not completed
const pendingOpen = pendingItems.filter(r => {
  const status = safe(r.status).toLowerCase();
  const completed = safe(r.completed_at).trim() !== '';
  return !completed && (status === 'pending' || status === 'open' || status === '');
});

const pendingCount = pendingOpen.length;

let byPriority = {};
for (const r of pendingOpen) {
  const p = safe(r.priority || 'normal').toLowerCase();
  byPriority[p] = (byPriority[p] || 0) + 1;
}

// Build small tables for email list & actions list (top 10 rows each)
const supportRowsHtml = todaysSupport
  .slice(0, 10)
  .map(r => {
    const timeStr = safe(r.timestamp).split('T')[1] || '';
    const hhmm = timeStr ? timeStr.slice(0, 5) : '';
    const from = htmlEscape(r.email_from || r.email || '');
    const subject = htmlEscape(r.subject || '(no subject)');
    const cat = htmlEscape(r.category || '');
    const subcat = htmlEscape(r.subcategory || '');
    const status = htmlEscape(r.draft_status || '');
    const needsAdmin = String(r.needs_admin).toUpperCase() === 'TRUE' || r.needs_admin === true;
    const createTask = String(r.create_task).toUpperCase() === 'TRUE' || r.create_task === true;

    return `
      <tr>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px; white-space:nowrap;">${hhmm}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px;">${from}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px;">${subject}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px; white-space:nowrap;">${cat}${subcat ? ' → ' + subcat : ''}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px;">${status}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px; text-align:center;">${needsAdmin ? '⚠️' : ''}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px; text-align:center;">${createTask ? '🧩' : ''}</td>
      </tr>`;
  })
  .join('') || `
    <tr>
      <td colspan="7" style="padding:10px; font-size:12px; color:#6b7280; text-align:center; border-bottom:1px solid #e5e7eb;">
        No support messages logged for today.
      </td>
    </tr>`;

const pendingRowsHtml = pendingOpen
  .slice(0, 10)
  .map(r => {
    const created = htmlEscape(r.created_at || '');
    const name = htmlEscape(r.customer_name || '');
    const email = htmlEscape(r.email || '');
    const action = htmlEscape(r.action_type || '');
    const priority = htmlEscape(r.priority || '');
    const status = htmlEscape(r.status || 'pending');

    return `
      <tr>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px; white-space:nowrap;">${created}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px;">${name}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px;">${email}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px;">${action}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px;">${priority}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e5e7eb; font-size:12px;">${status}</td>
      </tr>`;
  })
  .join('') || `
    <tr>
      <td colspan="6" style="padding:10px; font-size:12px; color:#6b7280; text-align:center; border-bottom:1px solid #e5e7eb;">
        No open or pending actions in the queue.
      </td>
    </tr>`;

// Summaries as text (plain-text fallback)
function summaryList(obj) {
  const entries = Object.entries(obj);
  if (!entries.length) return 'none';
  return entries.map(([k, v]) => `${k}: ${v}`).join(', ');
}

const textLines = [];
textLines.push(`GlassBag – Daily Support Digest (${todayIso})`);
textLines.push('');
textLines.push('SUPPORT ACTIVITY (today)');
textLines.push(`- Total messages: ${totalMessages}`);
textLines.push(`- Needs admin review: ${needsAdminCount}`);
textLines.push(`- Create task: ${createTaskCount}`);
textLines.push(`- Auto-send eligible: ${autoSendCount}`);
textLines.push(`- Processed/sent: ${processedCount}`);
textLines.push(`- By category: ${summaryList(byCategory)}`);
textLines.push(`- By draft status: ${summaryList(byDraftStatus)}`);
textLines.push('');
textLines.push('PENDING ACTIONS');
textLines.push(`- Open/pending actions: ${pendingCount}`);
textLines.push(`- By priority: ${summaryList(byPriority)}`);
textLines.push('');
textLines.push('For full details, check:');
textLines.push('- Main Support Inbox Log');
textLines.push('- Pending Actions Queue');

const emailBodyText = textLines.join('\n');

// Prettier HTML email
const emailBodyHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8" />
  <title>GlassBag – Daily Support Digest (${todayIso})</title>
</head>
<body style="margin:0; padding:0; background-color:#f4f6f8; font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f8; padding:24px 0;">
    <tr>
      <td align="center">
        <table width="100%" cellpadding="0" cellspacing="0" style="max-width:900px; background-color:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 6px 18px rgba(15,23,42,0.10);">
          <!-- Header -->
          <tr>
            <td style="background:linear-gradient(135deg,#16a34a,#15803d); padding:18px 24px; color:#ffffff;">
              <table width="100%" cellpadding="0" cellspacing="0">
                <tr>
                  <td style="font-size:20px; font-weight:600;">GlassBag – Daily Support Digest</td>
                  <td style="text-align:right; font-size:12px; opacity:0.9;">${todayIso}</td>
                </tr>
              </table>
              <p style="margin:8px 0 0; font-size:13px; opacity:0.9;">
                Snapshot of today's support activity and open follow-ups.
              </p>
            </td>
          </tr>

          <!-- Intro -->
          <tr>
            <td style="padding:16px 24px 8px; font-size:13px; color:#4b5563;">
              <p style="margin:0 0 6px;">Hi Mark,</p>
              <p style="margin:0;">Here’s a quick overview you can scan in under a minute.</p>
            </td>
          </tr>

          <!-- KPI chips row -->
          <tr>
            <td style="padding:8px 24px 16px;">
              <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">
                <tr>
                  <td style="width:25%; padding:6px 6px 6px 0;">
                    <div style="border-radius:999px; background:#ecfdf3; border:1px solid #bbf7d0; padding:8px 12px; font-size:12px; color:#166534;">
                      <div style="font-size:11px; text-transform:uppercase; letter-spacing:0.05em; opacity:0.8;">Total messages</div>
                      <div style="font-size:18px; font-weight:700; margin-top:2px;">${totalMessages}</div>
                    </div>
                  </td>
                  <td style="width:25%; padding:6px;">
                    <div style="border-radius:999px; background:#fef2f2; border:1px solid #fecaca; padding:8px 12px; font-size:12px; color:#b91c1c;">
                      <div style="font-size:11px; text-transform:uppercase; letter-spacing:0.05em; opacity:0.8;">Needs admin</div>
                      <div style="font-size:18px; font-weight:700; margin-top:2px;">${needsAdminCount}</div>
                    </div>
                  </td>
                  <td style="width:25%; padding:6px;">
                    <div style="border-radius:999px; background:#eff6ff; border:1px solid #bfdbfe; padding:8px 12px; font-size:12px; color:#1d4ed8;">
                      <div style="font-size:11px; text-transform:uppercase; letter-spacing:0.05em; opacity:0.8;">Tasks created</div>
                      <div style="font-size:18px; font-weight:700; margin-top:2px;">${createTaskCount}</div>
                    </div>
                  </td>
                  <td style="width:25%; padding:6px 0 6px 6px;">
                    <div style="border-radius:999px; background:#fffbeb; border:1px solid #facc15; padding:8px 12px; font-size:12px; color:#854d0e;">
                      <div style="font-size:11px; text-transform:uppercase; letter-spacing:0.05em; opacity:0.8;">Pending actions</div>
                      <div style="font-size:18px; font-weight:700; margin-top:2px;">${pendingCount}</div>
                    </div>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <!-- Summary lists -->
          <tr>
            <td style="padding:0 24px 16px;">
              <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">
                <tr>
                  <td style="width:50%; padding-right:8px; vertical-align:top;">
                    <div style="border-radius:10px; border:1px solid #e5e7eb; background:#f9fafb; padding:10px 12px; font-size:12px; color:#374151;">
                      <div style="font-size:11px; text-transform:uppercase; letter-spacing:0.05em; color:#6b7280; margin-bottom:4px;">By category</div>
                      <ul style="margin:0; padding-left:16px; list-style-type:disc;">
                        ${
                          Object.entries(byCategory).length
                            ? Object.entries(byCategory)
                                .map(([k, v]) => `<li>${htmlEscape(k)}: <strong>${v}</strong></li>`)
                                .join('')
                            : '<li>No messages today</li>'
                        }
                      </ul>
                    </div>
                  </td>
                  <td style="width:50%; padding-left:8px; vertical-align:top;">
                    <div style="border-radius:10px; border:1px solid #e5e7eb; background:#f9fafb; padding:10px 12px; font-size:12px; color:#374151;">
                      <div style="font-size:11px; text-transform:uppercase; letter-spacing:0.05em; color:#6b7280; margin-bottom:4px;">By draft status</div>
                      <ul style="margin:0; padding-left:16px; list-style-type:disc;">
                        ${
                          Object.entries(byDraftStatus).length
                            ? Object.entries(byDraftStatus)
                                .map(([k, v]) => `<li>${htmlEscape(k)}: <strong>${v}</strong></li>`)
                                .join('')
                            : '<li>No messages today</li>'
                        }
                      </ul>
                    </div>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <!-- Support table -->
          <tr>
            <td style="padding:0 24px 16px;">
              <h2 style="margin:0 0 6px; font-size:14px; color:#111827;">Today's support messages (top 10)</h2>
              <p style="margin:0 0 8px; font-size:11px; color:#6b7280;">⚠️ = needs admin review &nbsp;·&nbsp; 🧩 = follow-up task created</p>
              <div style="border-radius:8px; border:1px solid #e5e7eb; overflow:hidden; background-color:#f9fafb;">
                <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">
                  <thead>
                    <tr style="background-color:#e5e7eb;">
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Time</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">From</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Subject</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Category</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Draft status</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:center;">Admin?</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:center;">Task?</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${supportRowsHtml}
                  </tbody>
                </table>
              </div>
            </td>
          </tr>

          <!-- Pending actions table -->
          <tr>
            <td style="padding:0 24px 20px;">
              <h2 style="margin:0 0 6px; font-size:14px; color:#111827;">Pending actions queue (top 10)</h2>
              <p style="margin:0 0 8px; font-size:11px; color:#6b7280;">Sorted as in your sheet – check the sheet for full list.</p>
              <div style="border-radius:8px; border:1px solid #e5e7eb; overflow:hidden; background-color:#ffffff;">
                <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">
                  <thead>
                    <tr style="background-color:#e5e7eb;">
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Created</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Customer</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Email</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Action type</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Priority</th>
                      <th style="padding:6px 8px; font-size:11px; text-align:left;">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${pendingRowsHtml}
                  </tbody>
                </table>
              </div>
            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td style="padding:12px 24px 18px; font-size:11px; color:#9ca3af; border-top:1px solid #e5e7eb;">
              <p style="margin:0 0 4px;">This email was generated automatically by the GlassBag Support System.</p>
              <p style="margin:0;">For full details, open “Main Support Inbox Log” and “Pending Actions Queue” in the Support System sheet.</p>
            </td>
          </tr>
        </table>
        <p style="margin:12px 0 0; font-size:11px; color:#9ca3af;">© ${new Date().getFullYear()} GlassBag.ie</p>
      </td>
    </tr>
  </table>
</body>
</html>
`;

const emailSubject = `GlassBag – Daily Support Digest (${todayIso})`;

return [{
  json: {
    digest_date: todayIso,
    email_subject: emailSubject,
    email_body: emailBodyText,
    email_body_html: emailBodyHtml
  }
}];
